import{_ as d,o as t,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Bridges","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/bridges.md","filePath":"concepts/bridges.md","lastUpdated":1793726242000}'),a={name:"concepts/bridges.md"};function r(i,e,c,n,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="bridges" tabindex="-1">Bridges <a class="header-anchor" href="#bridges" aria-label="Permalink to &quot;Bridges&quot;">​</a></h1><p>Nostr is kernl&#39;s identity and resolution layer. It is not the only protocol kernl speaks. A bridge is a shell-owned service that resolves a protocol-specific locator to bytes, a job or a conversation, behind the same consent and quota model as everything else. Bridges are named by what they do for the user, never by the protocol they speak (<a href="./../decisions#d-010">D-010</a>).</p><h2 id="locators" tabindex="-1">Locators <a class="header-anchor" href="#locators" aria-label="Permalink to &quot;Locators&quot;">​</a></h2><p>A <code>Locator</code> is a parsed address: a lowercase <code>scheme</code> without the colon, the <code>raw</code> string, and scheme-specific <code>fields</code>, each a string or a list of strings. <code>parseLocator(uri)</code> produces it.</p><table tabindex="0"><thead><tr><th>Scheme</th><th>Fields</th><th>Notes</th></tr></thead><tbody><tr><td><code>https</code>, <code>http</code>, <code>ws</code>, <code>wss</code></td><td><code>origin</code>, <code>host</code> (with port when present), <code>path</code> (pathname plus query, no fragment)</td><td><code>HTTPS://Example.com:8443/a/b?c=1#frag</code> gives scheme <code>https</code>, origin <code>https://example.com:8443</code>, host <code>example.com:8443</code>, path <code>/a/b?c=1</code>. A web URL whose path ends in <code>.nzb</code> is parsed as an <code>nzb</code> locator instead.</td></tr><tr><td><code>magnet</code></td><td><code>infoHash</code> (40 lowercase hex; a 32-character base32 hash is normalised to hex), <code>name</code> (from <code>dn</code>, absent when not given), <code>trackers</code> (list from every <code>tr</code>), <code>webSeeds</code> (list from every <code>ws</code>)</td><td>A magnet without a <code>urn:btih:</code> hash of either length fails with <code>invalid:magnet-missing-hash</code>.</td></tr><tr><td><code>nzb</code></td><td><code>url</code> (the <code>http:</code> or <code>https:</code> document URL), <code>name</code> (the URL&#39;s <code>name</code> query parameter, else its last path segment, decoded)</td><td>Two spellings: <code>nzb://</code> followed by the URL-encoded document URL, or any web URL ending in <code>.nzb</code>. A wrapped URL with another scheme fails with <code>invalid:locator</code>.</td></tr><tr><td><code>slsk</code></td><td><code>user</code>, <code>path</code> (both decoded)</td><td><code>slsk://user/path/to/file</code>. Both parts are required; <code>slsk://ada</code>, <code>slsk://ada/</code> and <code>slsk:///path</code> fail with <code>invalid:locator</code>.</td></tr><tr><td><code>mailto</code></td><td><code>address</code> (the decoded address part as written), <code>addresses</code> (list split on <code>,</code> and trimmed), <code>subject</code> and <code>body</code> (only when present)</td><td><code>mailto:?subject=Hello</code> fails with <code>invalid:locator</code>.</td></tr><tr><td>anything else</td><td>none</td><td><code>ftp://files.example/pub/x</code> is a locator with scheme <code>ftp</code> and no fields; the registry will report <code>unavailable:no-bridge</code> for it.</td></tr></tbody></table><p>Strings without a scheme (<code>just words</code>, <code>/relative/path</code>, <code>1abc:not-scheme</code>, the empty string) fail with <code>invalid:locator</code>. <code>isNzbUrl(url)</code> is the test the parser uses for the <code>.nzb</code> route. <code>formatLocator(locator)</code> returns a label without the scheme: the magnet <code>name</code> or else the hash, the NZB <code>name</code>, the last segment of the Soulseek path or else the user, the mail addresses joined with <code>, </code>, the web <code>host</code>, or the raw string after its scheme for unknown schemes. See <code>locators.feature</code>.</p><h2 id="the-bridge-contract" tabindex="-1">The bridge contract <a class="header-anchor" href="#the-bridge-contract" aria-label="Permalink to &quot;The bridge contract&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bridge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;http&#39; | &#39;torrent&#39; | &#39;nzb&#39; | &#39;soulseek&#39; | &#39;mail&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> label</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;downloads&#39; | &#39;sharing&#39; | &#39;mail&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> schemes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  readonly</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> exposure</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BridgeExposure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  availability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BridgeAvailability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">locator</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Locator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">context</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BridgeContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BridgeResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>resolve</code> receives a <code>BridgeContext</code>: the <code>requester</code> (a verified applet identity <code>{ dTag, hash }</code>, or <code>&#39;shell&#39;</code> for the user&#39;s own request), an optional <code>AbortSignal</code> and optional headers. It returns one of three <code>BridgeResult</code> shapes:</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>Payload</th><th>Used by</th></tr></thead><tbody><tr><td><code>bytes</code></td><td>a <code>Response</code></td><td>HTTP</td></tr><tr><td><code>job</code></td><td><code>{ id, label }</code> for a long-running transfer</td><td>torrent, NZB, Soulseek</td></tr><tr><td><code>conversation</code></td><td><code>{ id, participants }</code></td><td>mail</td></tr></tbody></table><h2 id="exposure-descriptions" tabindex="-1">Exposure descriptions <a class="header-anchor" href="#exposure-descriptions" aria-label="Permalink to &quot;Exposure descriptions&quot;">​</a></h2><p>The user sees a bridge before they use it, and what they see is its <code>BridgeExposure</code>: three booleans, rendered as plain sentences by <code>describeBridge</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Row label</th><th>Question it answers</th></tr></thead><tbody><tr><td><code>revealsAddress</code></td><td>Shares your network address</td><td>Does the remote party learn the user&#39;s network address?</td></tr><tr><td><code>encryptedInTransit</code></td><td>Encrypted in transit</td><td>Is the transfer encrypted on the wire?</td></tr><tr><td><code>publicActivity</code></td><td>Activity visible to others</td><td>Can other participants see what the user is fetching?</td></tr></tbody></table><p><code>describeBridge(bridge)</code> returns, in order: <code>Used for</code> (the label), <code>Status</code> (<code>ready</code>, or <code>not available</code> followed by a <code>Reason</code> row with the bare reason such as <code>no-backend</code>), then the three exposure rows as <code>yes</code>/<code>no</code>. No row names a protocol. These are descriptions, not scores; like messaging providers, bridges are not ranked. See <code>describe.feature</code>.</p><h2 id="the-registry-and-consent" tabindex="-1">The registry and consent <a class="header-anchor" href="#the-registry-and-consent" aria-label="Permalink to &quot;The registry and consent&quot;">​</a></h2><p>The shell holds one <code>BridgeRegistry</code>, built with <code>createBridgeRegistry({ authorize?, onResolve? })</code>:</p><ul><li><code>register(bridge)</code> adds a bridge. A second bridge with the same id throws <code>invalid:duplicate-bridge &lt;id&gt;</code>; a bridge claiming a scheme another bridge serves throws <code>invalid:scheme-taken &lt;scheme&gt;</code>. Schemes are compared lowercase with any trailing colon removed.</li><li><code>forScheme(scheme)</code> finds the bridge that serves a scheme, with the same normalisation (<code>NZB:</code> finds the <code>nzb</code> bridge).</li><li><code>resolve(uri, context)</code> parses, routes, checks availability, authorises and resolves, in that order, and stops at the first failure.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Failure reason</th><th><code>BridgeResolveEvent.bridge</code></th></tr></thead><tbody><tr><td>parse</td><td><code>invalid:locator</code>, <code>invalid:magnet-missing-hash</code></td><td><code>none</code>, scheme <code>&quot;&quot;</code></td></tr><tr><td>route</td><td><code>unavailable:no-bridge</code></td><td><code>none</code></td></tr><tr><td>availability</td><td><code>unavailable:&lt;reason&gt;</code> from the bridge</td><td>the bridge id</td></tr><tr><td>authorise</td><td><code>denied:bridge</code></td><td>the bridge id</td></tr><tr><td>resolve</td><td>whatever the bridge threw (<code>denied:…</code>, <code>unavailable:…</code>, <code>invalid:…</code>); a non-<code>Error</code> rejection is reported as its text</td><td>the bridge id</td></tr></tbody></table><p>Every outcome, successful or not, is reported to <code>onResolve</code> as <code>{ bridge, scheme, ok, reason? }</code>. The authoriser is a <code>BridgeAuthorizer</code>: <code>(locator, bridge, context) =&gt; boolean | Promise&lt;boolean&gt;</code>. Without one, every request is allowed. The composed shell has none: <code>createKernl</code> builds its registry with <code>createDefaultBridges()</code> and no <code>authorize</code>, so a <code>resource</code> request from an applet that holds the <code>resource</code> grant is checked by the HTTP bridge&#39;s policy and nothing else. There is no per-host consent prompt and no per-host grant in this draft (<a href="./../alpha-status#what-does-not-work-yet">Alpha status</a>); wiring one is on the <a href="./../roadmap#_6-guard">Roadmap</a>. A host can pass its own registry with an <code>authorize</code> hook in <code>KernlOptions.bridges</code>. See <code>registry.feature</code>.</p><h2 id="the-http-bridge" tabindex="-1">The HTTP bridge <a class="header-anchor" href="#the-http-bridge" aria-label="Permalink to &quot;The HTTP bridge&quot;">​</a></h2><p><code>createHttpBridge({ policy?, fetch?, resolveHost? })</code> is complete and serves the <code>resource</code> NAP domain. Its id is <code>http</code>, its label <code>downloads</code>, and its <code>HttpPolicy</code> is <code>DEFAULT_HTTP_POLICY</code> with any <code>policy</code> overrides merged in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Why</th></tr></thead><tbody><tr><td><code>allowedSchemes</code></td><td><code>[&#39;https:&#39;]</code> (<code>URL.protocol</code> form, colon included)</td><td>Plain HTTP would make <code>encryptedInTransit</code> a lie.</td></tr><tr><td><code>maxRedirects</code></td><td><code>3</code></td><td>Enough for a CDN hop; too few for a redirect loop to be useful.</td></tr><tr><td><code>maxBytes</code></td><td><code>10485760</code> (10 MiB)</td><td>Larger payloads belong to a <code>job</code> bridge, not to an applet&#39;s memory.</td></tr><tr><td><code>timeoutMs</code></td><td><code>20000</code></td><td>A slow origin should fail visibly, not hold the window&#39;s resource budget.</td></tr><tr><td><code>allowPrivateHosts</code></td><td><code>[]</code></td><td>Private-address block on by default.</td></tr></tbody></table><p>The bridge&#39;s <code>schemes</code> and <code>exposure</code> follow the policy: with the default it serves <code>https</code> only and declares <code>revealsAddress: true</code>, <code>encryptedInTransit: true</code>, <code>publicActivity: false</code>. A shell that adds <code>&#39;http:&#39;</code> to <code>allowedSchemes</code> gets a bridge that serves <code>https</code> and <code>http</code> and declares <code>encryptedInTransit: false</code> (<code>http-bridge.feature</code>, scenario &quot;the shell can admit the unencrypted scheme and the bridge says so&quot;).</p><p>Before every request, including every redirect hop, the bridge checks the URL. A scheme outside the policy fails with <code>denied:scheme &lt;protocol&gt;</code>. A host that <code>isBlockedHostname</code> or <code>isPrivateAddress</code> recognises fails with <code>denied:private-address &lt;host&gt;</code>, unless it is listed in <code>allowPrivateHosts</code>. When <code>resolveHost</code> is supplied, the host&#39;s addresses are checked too and a private one fails with <code>denied:private-address &lt;host&gt; -&gt; &lt;ip&gt;</code>. No caller supplies it in this draft: <code>createDefaultBridges()</code> creates the HTTP bridge without <code>http.resolveHost</code>, so the composed shell judges a hostname by <code>isBlockedHostname</code> and <code>isPrivateAddress</code> on the literal alone. A public name that resolves to a private address is not caught, and there is no DNS-rebinding protection. Even with a resolver, the fetch API cannot pin a connection to the validated address, so the check would narrow the rebinding window without closing it.</p><table tabindex="0"><thead><tr><th>Check</th><th>Blocked</th></tr></thead><tbody><tr><td><code>isPrivateAddress</code>, IPv4</td><td><code>0.0.0.0/8</code>, <code>10.0.0.0/8</code>, <code>100.64.0.0/10</code>, <code>127.0.0.0/8</code>, <code>169.254.0.0/16</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>, <code>224.0.0.0/3</code> (multicast, reserved and broadcast)</td></tr><tr><td><code>isPrivateAddress</code>, IPv6</td><td><code>::</code> and <code>::1</code>, <code>fe80::/10</code>, <code>fc00::/7</code>, <code>ff00::/8</code>; brackets are stripped; an IPv4-mapped address (<code>::ffff:127.0.0.1</code>) is judged as its IPv4 part</td></tr><tr><td><code>isBlockedHostname</code></td><td><code>localhost</code> and any name under <code>.localhost</code>, <code>.local</code> or <code>.internal</code>, case-insensitively, trailing dot ignored</td></tr></tbody></table><p>Strings that are neither a valid IPv4 nor a valid IPv6 literal (<code>1.2.3</code>, <code>256.1.1.1</code>, <code>1::2::3</code>, <code>example.com</code>) are not addresses and pass <code>isPrivateAddress</code>; a hostname is judged by <code>isBlockedHostname</code> and, only if a resolver was supplied, by what it resolves to.</p><p>Redirects (<code>301</code>, <code>302</code>, <code>303</code>, <code>307</code>, <code>308</code>) are followed manually, so each hop passes the same checks. More than <code>maxRedirects</code> hops fails with <code>denied:too-many-redirects</code>; a redirect without a usable <code>Location</code> fails with <code>invalid:redirect</code>. Requests race <code>AbortSignal.timeout(timeoutMs)</code> and the caller&#39;s signal: the time limit fails with <code>unavailable:timeout</code>, a caller cancel with <code>unavailable:aborted</code>, any other fetch failure with <code>unavailable:network &lt;message&gt;</code>. Caller headers are forwarded on every hop.</p><p>A response whose <code>content-length</code> exceeds <code>maxBytes</code> fails with <code>denied:too-large</code> before the body is read. Otherwise the <code>Response</code> is returned with its status and headers, and its body is streamed through a counter that errors the stream with <code>denied:too-large</code> the moment the limit is crossed. The guard&#39;s <code>hiddenResourceAllowance</code>, <code>maxResourceEnvelopeBytes</code> and <code>resource:bytes</code> rate apply before the request reaches the bridge.</p><h2 id="backend-driven-bridges" tabindex="-1">Backend-driven bridges <a class="header-anchor" href="#backend-driven-bridges" aria-label="Permalink to &quot;Backend-driven bridges&quot;">​</a></h2><p>Four bridges are complete up to the backend interface they call, and ship without a backend. Without one, <code>availability()</code> returns <code>{ available: false, reason: &#39;no-backend&#39; }</code>, <code>describeBridge</code> shows <code>Status: not available</code> and <code>Reason: no-backend</code>, and <code>resolve()</code> rejects with <code>unavailable:no-backend</code>. Nothing pretends to work.</p><table tabindex="0"><thead><tr><th>Bridge id</th><th>Label</th><th>Scheme</th><th>Reveals address</th><th>Encrypted in transit</th><th>Public activity</th><th>Backend interface</th><th>Call made</th></tr></thead><tbody><tr><td><code>torrent</code></td><td><code>downloads</code></td><td><code>magnet</code></td><td>yes</td><td>no</td><td>yes</td><td><code>TorrentBackend</code></td><td><code>add(infoHash, trackers, context) → { id, name }</code></td></tr><tr><td><code>nzb</code></td><td><code>downloads</code></td><td><code>nzb</code></td><td>yes</td><td>yes</td><td>no</td><td><code>NzbBackend</code></td><td><code>add(url, context) → { id, name }</code></td></tr><tr><td><code>soulseek</code></td><td><code>sharing</code></td><td><code>slsk</code></td><td>yes</td><td>no</td><td>yes</td><td><code>SoulseekBackend</code></td><td><code>download(user, path, context) → { id, name }</code></td></tr><tr><td><code>mail</code></td><td><code>mail</code></td><td><code>mailto</code></td><td>no</td><td>yes</td><td>no</td><td><code>MailBackend</code></td><td><code>open(address, subject | undefined, context) → { id }</code></td></tr></tbody></table><p>The first three return <code>{ kind: &#39;job&#39;, id, label: name }</code>; the mail bridge returns <code>{ kind: &#39;conversation&#39;, id, participants: addresses }</code>. Fields are read from the locator before the backend is called; a locator missing one rejects with <code>invalid:locator-missing-&lt;field&gt;</code> (<code>backend-bridges.feature</code>, scenario &quot;a locator missing a required field is rejected before the backend is called&quot;). Supplying a backend is a shell change plus a docs change; see <a href="./../how-tos/add-a-bridge-backend">Add a bridge backend</a>. The order in which backends are planned is in the <a href="./../roadmap">Roadmap</a>.</p><h2 id="the-resource-resolver" tabindex="-1">The resource resolver <a class="header-anchor" href="#the-resource-resolver" aria-label="Permalink to &quot;The resource resolver&quot;">​</a></h2><p>kehto&#39;s resource service takes a <code>fetch(url, init)</code> function. <code>createBridgeResourceResolver(registry, { requesterFor? })</code> returns one over the registry. The requester is <code>init.requester</code> when the service names it, else <code>requesterFor(init)</code> when the shell supplied a way to derive it (for example from the window id), else <code>&#39;shell&#39;</code>. <code>init.signal</code> and <code>init.headers</code> reach the bridge. A <code>bytes</code> result is returned as its <code>Response</code>; a <code>job</code> or <code>conversation</code> result becomes <code>Response.json(result, { status: 202 })</code> so the caller can show progress; a failure rejects with the registry&#39;s prefixed reason, which the service maps to its error envelope. See <code>resource-resolver.feature</code>.</p><h2 id="error-reasons" tabindex="-1">Error reasons <a class="header-anchor" href="#error-reasons" aria-label="Permalink to &quot;Error reasons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reason</th><th>Thrown by</th></tr></thead><tbody><tr><td><code>invalid:locator</code></td><td><code>parseLocator</code> for anything that is not a locator or a malformed web, NZB, Soulseek or mail locator</td></tr><tr><td><code>invalid:magnet-missing-hash</code></td><td><code>parseLocator</code> for a magnet without a <code>urn:btih:</code> hash</td></tr><tr><td><code>invalid:locator-missing-&lt;field&gt;</code></td><td>a backend-driven bridge whose locator lacks <code>infoHash</code>, <code>url</code>, <code>user</code>, <code>path</code> or <code>address</code></td></tr><tr><td><code>invalid:duplicate-bridge &lt;id&gt;</code>, <code>invalid:scheme-taken &lt;scheme&gt;</code></td><td><code>BridgeRegistry.register</code></td></tr><tr><td><code>invalid:redirect</code></td><td>HTTP bridge, redirect without a usable <code>Location</code></td></tr><tr><td><code>unavailable:no-bridge</code></td><td><code>BridgeRegistry.resolve</code>, no bridge serves the scheme</td></tr><tr><td><code>unavailable:no-backend</code></td><td>a backend-driven bridge without a backend (<code>availability().reason</code> is the bare <code>no-backend</code>)</td></tr><tr><td><code>unavailable:timeout</code>, <code>unavailable:aborted</code>, <code>unavailable:network &lt;message&gt;</code></td><td>HTTP bridge</td></tr><tr><td><code>denied:bridge</code></td><td><code>BridgeRegistry.resolve</code>, the authoriser said no</td></tr><tr><td><code>denied:scheme &lt;protocol&gt;</code>, <code>denied:private-address &lt;host&gt;</code>, <code>denied:private-address &lt;host&gt; -&gt; &lt;ip&gt;</code>, <code>denied:too-many-redirects</code>, <code>denied:too-large</code></td><td>HTTP bridge</td></tr></tbody></table><h2 id="why-bridges-are-shell-owned" tabindex="-1">Why bridges are shell-owned <a class="header-anchor" href="#why-bridges-are-shell-owned" aria-label="Permalink to &quot;Why bridges are shell-owned&quot;">​</a></h2><p>An applet could, in principle, be given a WebRTC or WebSocket path and speak these protocols itself. kernl does not allow that, because the CSP <a href="./guard#why-csp-never-loosens">never loosens</a>. Routing every protocol through a shell service means every protocol gets the same grant, the same quota, the same exposure description and the same revocation, and a consent prompt per request can be added in one place. The applet asks for a locator; the user decides; the shell does the talking.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../packages/bridges"><code>@kernl/bridges</code></a></li><li><a href="./../policies/security-posture">Security posture</a></li></ul>`,40)])])}const b=d(a,[["render",r]]);export{g as __pageData,b as default};
